-- SOURCE: supabase/schema/catalog_enrichment_wave_41_format_russia_exact_2026_08_17.sql
-- VeloQuest catalog enrichment wave 41.
-- Russia-first FORMAT cohort from exact format.bike product pages.
-- 20 cards have explicit year/category/frame/wheel/drivetrain/brakes/cassette.
-- Images were independently verified HTTPS 200 on 2026-08-17.
-- format.bike identifies itself as the official FORMAT representative in Russia;
-- media is therefore classified authorized_retailer, not manufacturer.
-- Factory fitment is exact-product evidence only; no compatibility/outcome is inferred.

begin;

on conflict (brand,model,model_year,trim,market) do update set
category=excluded.category,specs=excluded.specs||public.bike_catalog_models.specs,manufacturer_url=excluded.manufacturer_url,evidence_checked_at=greatest(public.bike_catalog_models.evidence_checked_at,excluded.evidence_checked_at),enabled=true;

on conflict (bike_id,image_url) do update set source_type=excluded.source_type,source_name=excluded.source_name,source_page_url=excluded.source_page_url,priority=least(public.bike_catalog_images.priority,excluded.priority),checked_at=excluded.checked_at,enabled=true;

select 'oem-'||m.id||'-rd',
case when lower(m.specs->>'drivetrain') like 'shimano%' then 'Shimano' when lower(m.specs->>'drivetrain') like 'sram%' then 'SRAM' when lower(m.specs->>'drivetrain') like 'microshift%' then 'Microshift' else 'Other' end,
m.specs->>'drivetrain','rear_derailleur',m.specs->>'drivetrain','{"evidence_scope":"FORMAT Russia exact-product OEM specification"}'::jsonb,1,m.manufacturer_url,'2026-08-17',true
from public.bike_catalog_models m where m.id like 'format-%-ru' and m.id in (
'format-1213-29-2026-ru','format-1312-29-2026-ru','format-1313-29-2026-ru','format-1314-plus-275-2026-ru','format-1412-29-2026-ru','format-1413-29-2026-ru','format-1443-700c-2026-ru','format-2222-700c-2026-ru','format-2322-700c-2026-ru','format-5413-26-2026-ru','format-6413-24-2026-ru','format-7413-20-2026-ru','format-1122-29-2026-ru','format-1212-29-2026-ru','format-1213-29-2025-ru','format-1313-29-2025-ru','format-1314-plus-275-2025-ru','format-1315-275-2025-ru','format-1413-29-2025-ru','format-2232-700c-2025-ru')
on conflict (id) do update set brand=excluded.brand,model=excluded.model,display_name=excluded.display_name,specs=excluded.specs,evidence_url=excluded.evidence_url,evidence_checked_at=excluded.evidence_checked_at,enabled=true;

select m.id,'oem-'||m.id||'-rd','factory_installed',m.manufacturer_url,'2026-08-17','Exact FORMAT Russia product specification.'
from public.bike_catalog_models m where m.id in (
'format-1213-29-2026-ru','format-1312-29-2026-ru','format-1313-29-2026-ru','format-1314-plus-275-2026-ru','format-1412-29-2026-ru','format-1413-29-2026-ru','format-1443-700c-2026-ru','format-2222-700c-2026-ru','format-2322-700c-2026-ru','format-5413-26-2026-ru','format-6413-24-2026-ru','format-7413-20-2026-ru','format-1122-29-2026-ru','format-1212-29-2026-ru','format-1213-29-2025-ru','format-1313-29-2025-ru','format-1314-plus-275-2025-ru','format-1315-275-2025-ru','format-1413-29-2025-ru','format-2232-700c-2025-ru')
on conflict (bike_id,component_id,fitment_type) do update set evidence_url=excluded.evidence_url,evidence_checked_at=excluded.evidence_checked_at,notes=excluded.notes;

commit;
